import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import axios from 'axios';

const HomePage = () => {
  const location = useLocation();
  const [userInfo, setUserInfo] = useState(null);
  const [error, setError] = useState(null);
  const [classes, setClasses] = useState([]);
  const [selectedClasses, setSelectedClasses] = useState([]);
  const [message, setMessage] = useState('');

  useEffect(() => {
    const fetchUserInfo = async () => {
      try {
        const accessToken = location.state.accessToken;
        const response = await axios.get('http://localhost:3001/salesforce/user-info', {
          params: { accessToken },
        });
        setUserInfo(response.data);
      } catch (error) {
        setError('Failed to load user information.');
      }
    };

    fetchUserInfo();
  }, [location.state.accessToken]);

  const fetchApexClasses = async () => {
    try {
      const response = await axios.get('http://localhost:3001/listApexClasses');
      setClasses(response.data.classes);
    } catch (error) {
      console.error('Error fetching Apex classes:', error);
    }
  };

  const handleCheckboxChange = (event) => {
    const className = event.target.value;
    if (event.target.checked) {
      setSelectedClasses([...selectedClasses, className]);
    } else {
      setSelectedClasses(selectedClasses.filter((name) => name !== className));
    }
  };

  const handleRetrieveClasses = async () => {
    try {
      const response = await axios.post('http://localhost:3001/retrieveApexClasses', {
        classNames: selectedClasses,
      });
      setMessage(response.data.message);
    } catch (error) {
      console.error('Error retrieving Apex classes:', error);
    }
  };

  return (
    <div>
      <h1>Welcome to the Home Page</h1>
      {error ? (
        <p>{error}</p>
      ) : userInfo ? (
        <div>
          <p>User ID: {userInfo.user_id}</p>
          <p>Name: {userInfo.name}</p>
          <p>Email: {userInfo.email}</p>
        </div>
      ) : (
        <p>Loading user information...</p>
      )}
      
      <h2>Select Apex Classes to Retrieve</h2>
      <button onClick={fetchApexClasses}>Retrieve Apex Classes</button>
      {classes.length > 0 ? (
        <div>
          <ul>
            {classes.map((apexClass) => (
              <li key={apexClass.Name}>
                <label>
                  <input
                    type="checkbox"
                    value={apexClass.Name}
                    onChange={handleCheckboxChange}
                  />
                  {apexClass.Name}
                </label>
              </li>
            ))}
          </ul>
          <button onClick={handleRetrieveClasses}>Retrieve Selected Classes</button>
          {message && <p>{message}</p>}
        </div>
      ) : (
        <p>No Apex classes to display. Click 'Retrieve Apex Classes' to load them.</p>
      )}
    </div>
  );
};

export default HomePage;
